visual.raw:
const rows = (ctx.data && ctx.data.objects) || [];
const data = rows.map(function (r) {
  return { name: (r.type === null || r.type === undefined || r.type === '') ? '未填写' : String(r.type), value: Number(r.logCount) || 0 };
});
data.sort(function (a, b) { return b.value - a.value; });
return {
  tooltip: { trigger: 'item', formatter: '{b}: {c} ({d}%)' },
  legend: { bottom: 0 },
  series: [
    { type: 'pie', name: '流水数', radius: '62%', center: ['50%', '42%'], data: data, label: { show: true, formatter: '{b}: {c}' } }
  ]
};
